def closestTaller(heights):
    n = len(heights)
    left = [-1] * n
    right = [-1] * n
    stack = []
    for i in range(n):
        while stack and heights[stack[-1]] <= heights[i]:
            stack.pop()
        left[i] = stack[-1] if stack else -1
        stack.append(i)
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and heights[stack[-1]] <= heights[i]:
            stack.pop()
        right[i] = stack[-1] if stack else -1
        stack.append(i)
    answer = []
    for i in range(n):
        a, b = left[i], right[i]
        if a == -1:
            answer.append(b)
        elif b == -1:
            answer.append(a)
        else:
            answer.append(a if i - a <= b - i else b)
    return answer
